600	fn populate_command_candidate(
601	    candidate: CompletionCandidate,
602	    cmd: &clap::Command,
603	    subcommand: &clap::Command,
604	) -> CompletionCandidate {
605	    candidate
606	        .help(subcommand.get_about().cloned())
607	        .id(Some(format!("command::{}", subcommand.get_name())))
608	        .tag(Some(
609	            cmd.get_subcommand_help_heading()
610	                .unwrap_or("Commands")
611	                .to_owned()
612	                .into(),
613	        ))
614	        .display_order(Some(subcommand.get_display_order()))
615	        .hide(subcommand.is_hide_set())
616	}
